// copied from https://www.shadertoy.com/view/XXGyWR
float Rand (vec2 _st) {
    return fract(sin(dot(_st.xy, vec2(12.9898,78.233)))*43758.5453123);
}

// most general quadratic curve
float QuadCurve(vec2 uv, float p, float a, float b, float c, float d, float e, float f){

    float x = uv.x,
          y = uv.y;

    return p/abs(a*x*x + 2.*b*x*y + c*y*y + d*x + e*y -f);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalize pixel coordinates 
    vec2 uv = ( fragCoord -.5*iResolution.xy ) / iResolution.y;

    // global variables
    float PI = 3.14159265,
          w0 = .6,
        seed = 0.1,
        phi0 = 0.,
           t = iTime;

    // draw n harmonicaly changing quadratic curves (hcqc)
    float mask = 0.,
           n = 100.;


    for(float i = 0.; i < n; i++){

        // generate 6 pairs of random real numbers 
        float wa[6], phia[6];

        for(float j = 0.; j < 6.; j++){

            float w = Rand(vec2(seed*(i+j+1.))),
                phi = Rand(vec2((seed+0.2)*(i+j+1.)));

            wa[int(j)] = w;
            phia[int(j)]=phi;
        }

        // draw a random hcqh 
        mask += clamp(QuadCurve(uv, 0.1, 
                10.*sin(w0*wa[0]*t+PI*phia[0]+phi0), 
                20.*sin(w0*wa[1]*t+PI*phia[1]+phi0), 
                20.*sin(w0*wa[2]*t+PI*phia[2]+phi0), 
                 2.*sin(w0*wa[3]*t+PI*phia[3]+phi0), 
                 2.*sin(w0*wa[4]*t+PI+phia[4]+phi0), 
                 .5*sin(w0*wa[5]*t+PI*phia[5]+phi0)),0.,10.);
    }
    // normalize mask 
    mask *= 1./n;


    // output to screen
    fragColor = vec4(mask);
}
